-- Run once after customer_thread_migration.sql.
-- Existing numeric session_id values are preserved as text, but new login sessions
-- will supply an opaque session_id generated by the browser.
ALTER TABLE cs_thread
  MODIFY COLUMN session_id VARCHAR(64) NOT NULL COMMENT 'frontend login-session identifier',
  DROP INDEX session_id,
  ADD INDEX idx_thread_user_session_update (user_id, session_id, is_deleted, update_time DESC);